class DB:
    def __init__(self):
        self.value = "v1"
        self.loads = 0
    def load(self):
        self.loads += 1
        return self.value

def simulate(n_requests, singleflight):
    db = DB()
    cache = {}          # 波次开始时 key 已过期（为空）
    inflight = {}
    waited = 0
    for _ in range(n_requests):
        key = "hot"
        if key in cache:
            continue
        if singleflight:
            if key in inflight:
                waited += 1          # 等待并复用他人结果，不回源
                continue
            inflight[key] = True
            db.load()                # 仅第一个请求真正回源
        else:
            db.load()                # 无保护：每个 miss 都回源
    return db.loads, waited

n = 200
for sf in [False, True]:
    loads, waited = simulate(n, sf)
    name = "单飞保护" if sf else "无保护  "
    print("%s: %d 并发 -> DB 回源 %d 次, 等待复用 %d 次" % (name, n, loads, waited))

l0, _ = simulate(n, False)
l1, w1 = simulate(n, True)
print("回源次数下降: %d -> %d (降低 %.1f%%)" % (l0, l1, 100.0 * (l0 - l1) / l0))
print("结论: 单飞保证同一 key 同一时刻只有一个线程回源，其余 %d 个请求等待并复用同一份结果 -> 击穿被消除" % w1)
